import os
from rich.console import Console
from io import TextIOBase

class BrokenPipeFile(TextIOBase):
    def write(self, s):
        raise BrokenPipeError()
    def flush(self):
        raise BrokenPipeError()

def test_broken_pipe():
    console = Console(file=BrokenPipeFile())
    try:
        console.print("Hello World")
        print("Successfully printed (should not happen if BrokenPipeError is raised)")
    except BrokenPipeError:
        print("Caught BrokenPipeError - this is what we want to avoid")
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")

    print(f"Console quiet: {console.quiet}")

if __name__ == "__main__":
    test_broken_pipe()

